from collections import Counter

unique_song_ids = set()
artist_counts = Counter()

for playlist in playlists:
    details = apis.spotify.show_playlist(playlist_id=playlist["playlist_id"], access_token=spotify_access_token)
    for song in details["songs"]:
        if song["id"] in unique_song_ids:
            continue
        unique_song_ids.add(song["id"])
        for artist in song["artists"]:
            artist_counts[artist["name"]] += 1

top3 = [name for name, count in artist_counts.most_common(3)]
answer = ",".join(top3)
print(answer)
